#include <iostream>
#include <string>

int main()
{
    std::string line;
    std::getline(std::cin, line);

    std::string clean;
    for (char c : line)
    {
        if (c >= 'a' && c <= 'z')      clean.push_back(c);
        else if (c >= 'A' && c <= 'Z') clean.push_back(static_cast<char>(c - 'A' + 'a'));
        else if (c >= '0' && c <= '9') clean.push_back(c);
    }

    bool pal{ true };
    std::size_t i{ 0 };
    std::size_t j{ clean.size() };
    while (i + 1 < j)
    {
        if (clean[i] != clean[j - 1]) { pal = false; break; }
        ++i;
        --j;
    }

    std::cout << "clean [" << clean << "]\n";
    std::cout << "palindrome " << (pal ? "yes" : "no") << "\n";

    return 0;
}
